'use client';

import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { FormEvent, useEffect, useState } from 'react';
import { ArrowLeft, ArrowRight, GitBranch } from 'lucide-react';
import { apiClient } from '@/lib/api-client';

function GoogleIcon() { return <svg aria-hidden="true" viewBox="0 0 24 24" width="18" height="18"><path fill="#4285F4" d="M21.35 12.23c0-.71-.06-1.4-.18-2.05H12v3.88h5.23a4.47 4.47 0 0 1-1.94 2.93v2.42h3.14c1.84-1.7 2.92-4.2 2.92-7.18Z"/><path fill="#34A853" d="M12 21.7c2.63 0 4.84-.87 6.45-2.35l-3.14-2.42c-.87.58-1.98.92-3.31.92-2.54 0-4.7-1.72-5.47-4.03H3.28v2.5A9.74 9.74 0 0 0 12 21.7Z"/><path fill="#FBBC05" d="M6.53 13.82a5.86 5.86 0 0 1 0-3.64v-2.5H3.28a9.73 9.73 0 0 0 0 8.64l3.25-2.5Z"/><path fill="#EA4335" d="M12 6.15c1.43 0 2.71.49 3.72 1.46l2.79-2.79C16.84 3.17 14.63 2.3 12 2.3a9.74 9.74 0 0 0-8.72 5.38l3.25 2.5C7.3 7.87 9.46 6.15 12 6.15Z"/></svg>; }
function GitHubIcon() { return <svg aria-hidden="true" viewBox="0 0 24 24" width="18" height="18" fill="currentColor"><path d="M12 .7a11.3 11.3 0 0 0-3.57 22.02c.57.1.78-.25.78-.55v-2.12c-3.17.69-3.84-1.34-3.84-1.34-.52-1.32-1.27-1.67-1.27-1.67-1.04-.71.08-.7.08-.7 1.15.08 1.76 1.18 1.76 1.18 1.02 1.75 2.68 1.25 3.33.96.1-.74.4-1.25.73-1.54-2.53-.29-5.2-1.27-5.2-5.66 0-1.25.45-2.27 1.18-3.07-.12-.29-.51-1.45.11-3.02 0 0 .96-.31 3.13 1.17A10.9 10.9 0 0 1 12 5.99c.97 0 1.94.13 2.85.39 2.17-1.48 3.13-1.17 3.13-1.17.62 1.57.23 2.73.11 3.02.73.8 1.18 1.82 1.18 3.07 0 4.4-2.68 5.36-5.22 5.65.41.35.78 1.04.78 2.1v3.11c0 .3.21.66.79.55A11.3 11.3 0 0 0 12 .7Z"/></svg>; }

export function AuthForm({ mode }: { mode: 'login' | 'register' }) {
  const router = useRouter(); const [name, setName] = useState(''); const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [error, setError] = useState(''); const [busy, setBusy] = useState(false); const isRegister = mode === 'register';
  function readableError(message?: string) { if (!message) return 'Unable to authenticate. Please try again.'; if (message.includes('oauth_accounts') || message.includes('relation')) return 'Authentication storage is not ready. Run the database migrations and try again.'; if (message.includes('already exists')) return 'An account with this email already exists. Try signing in instead.'; if (message.includes('Invalid email or password')) return 'The email or password is incorrect.'; if (message.includes('fetch') || message.includes('Network')) return 'The API is unavailable. Make sure the backend is running.'; return message; }
  useEffect(() => { const oauthError = new URLSearchParams(window.location.search).get('error'); if (oauthError) setError(readableError(oauthError)); void apiClient.auth.me().then((result) => { if (result.success && result.data) router.replace('/dashboard'); }); }, [router]);
  async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setError(''); setBusy(true); try { const result = isRegister ? await apiClient.auth.register({ name, email, password }) : await apiClient.auth.login({ email, password }); if (!result.success || !result.data) { setError(readableError(result.error?.message)); return; } window.localStorage.setItem('versionflow_access_token', result.data.tokens.accessToken); window.localStorage.setItem('versionflow_refresh_token', result.data.tokens.refreshToken); router.push('/dashboard'); } catch (cause) { setError(readableError(cause instanceof Error ? cause.message : undefined)); } finally { setBusy(false); } }
  const googleUrl = `${process.env.NEXT_PUBLIC_API_URL || 'http://localhost:4000/api/v1'}/auth/google`;
  const githubUrl = `${process.env.NEXT_PUBLIC_API_URL || 'http://localhost:4000/api/v1'}/auth/github`;
  return <main className="auth-page"><div className="auth-card"><Link href="/" className="auth-brand"><span className="brand-mark"><GitBranch size={16} /></span><span>version<span>flow</span></span></Link><div className="auth-heading"><p className="section-kicker">Change APIs with confidence</p><h1>{isRegister ? 'Create your workspace.' : 'Welcome back.'}</h1><p>{isRegister ? "Start with a personal workspace. Invite your team when you're ready." : 'Sign in to open your API ecosystem workspace.'}</p></div><div className="auth-provider-buttons"><a className="google-button" href={googleUrl}><GoogleIcon /><span>Continue with Google</span></a><a className="google-button github-button" href={githubUrl}><GitHubIcon /><span>Continue with GitHub</span></a></div><div className="auth-divider"><span>or use email</span></div><form onSubmit={submit}>{isRegister && <label>Name<input value={name} onChange={(event) => setName(event.target.value)} placeholder="Om Vatsal" required /></label>}<label>Email<input type="email" value={email} onChange={(event) => setEmail(event.target.value)} placeholder="you@company.com" required /></label><label>Password<input type="password" value={password} onChange={(event) => setPassword(event.target.value)} placeholder={isRegister ? 'At least 12 characters' : 'Your password'} minLength={isRegister ? 12 : 1} required /></label>{error && <p className="auth-error" role="alert">{error}</p>}<button className="button button-primary auth-submit" disabled={busy}>{busy ? 'Working…' : isRegister ? 'Create workspace' : 'Sign in'} <ArrowRight size={16} /></button></form><p className="auth-switch">{isRegister ? 'Already have an account?' : 'New to VersionFlow?'} <Link href={isRegister ? '/auth/login' : '/auth/register'}>{isRegister ? 'Sign in' : 'Create an account'}</Link></p></div><Link href="/" className="auth-back"><ArrowLeft size={14} /> Back to VersionFlow</Link></main>;
}
